public class RaceControlPanel:RoundedPanel {
    readonly Career state;readonly Entry entry;readonly Action changed;readonly OptionTile[] engine=new OptionTile[3],driving=new OptionTile[3];readonly TyreTile[] tyres=new TyreTile[5];internal OptionTile[] EngineChoices {get{return engine;}}
    string selected="M";readonly SoftButton pit=new SoftButton{Text="В боксы",Primary=true};
    public RaceControlPanel(Career s,Entry e,Action onChange){state=s;entry=e;changed=onChange;BackColor=Theme.Card;for(int i=0;i<3;i++){int mode=i;engine[i]=new OptionTile(Powertrain.Modes[i]){Selected=e.EngineMode==i};driving[i]=new OptionTile(Powertrain.Modes[i]){Selected=e.DrivingMode==i};Controls.Add(engine[i]);Controls.Add(driving[i]);engine[i].Click+=(o,a)=>ChangeModes(mode,entry.DrivingMode);driving[i].Click+=(o,a)=>ChangeModes(entry.EngineMode,mode);}var codes=new[]{"S","M","H","I","W"};for(int i=0;i<5;i++){string code=codes[i];tyres[i]=new TyreTile(code,code){Selected=code==selected};Controls.Add(tyres[i]);tyres[i].Click+=(o,a)=>{selected=code;for(int j=0;j<5;j++)tyres[j].Selected=codes[j]==selected;};}Controls.Add(pit);pit.Click+=(o,a)=>RequestPit();Resize+=(o,a)=>LayoutChoices();LayoutChoices();}
    void ChangeModes(int motor,int style){try{Powertrain.SetModes(state,entry.Id,motor,style);for(int i=0;i<3;i++){engine[i].Selected=i==motor;driving[i].Selected=i==style;}changed();}catch(InvalidOperationException){}}
    internal void RequestPit(){if(entry.Dnf||entry.Finished)return;Engine.Pit(state,entry.Id,selected);changed();}
    void LayoutChoices(){float scale=Height/328f;int w=(Width-36)/3;for(int i=0;i<3;i++){engine[i].Bounds=new Rectangle(12+i*(w+6),(int)(91*scale),w,(int)(32*scale));driving[i].Bounds=new Rectangle(12+i*(w+6),(int)(148*scale),w,(int)(32*scale));}int tw=(Width-36)/5;for(int i=0;i<5;i++)tyres[i].Bounds=new Rectangle(12+i*(tw+3),(int)(200*scale),tw,(int)(49*scale));pit.Bounds=new Rectangle(Width-132,(int)(258*scale),120,(int)(33*scale));}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.ScaleTransform(1,Height/328f);g.SmoothingMode=SmoothingMode.AntiAlias;var person=Engine.Person(state,entry.Id);Theme.ImageFit(g,DriverPhotos.Get(person),new Rectangle(10,9,42,54));Draw(g,person.Name,new Rectangle(62,12,Width-74,25),16,Color.White,true);Draw(g,entry.Dnf?"Сход: "+entry.Reason:entry.Tyre+" / износ "+entry.TyreWear.ToString("0")+"% / P"+entry.RacePosition,new Rectangle(62,39,Width-74,25),12,Theme.Muted);Draw(g,"ДВИГАТЕЛЬ",new Rectangle(13,70,Width-20,20),10,Theme.Muted);Draw(g,"ПИЛОТАЖ",new Rectangle(13,128,Width-20,20),10,Theme.Muted);Draw(g,"ШИНЫ ДЛЯ ПИТ-СТОПА",new Rectangle(13,182,Width-20,18),10,Theme.Muted);Draw(g,entry.PitRequested?"Вызов принят":"Остановок: "+entry.Stops,new Rectangle(13,265,Width-150,20),12,entry.PitRequested?Theme.Red:Theme.Muted);var c=Powertrain.Car(state,entry);Draw(g,"Ресурс: ДВС "+c.Condition[0].ToString("0")+"% · ERS "+c.Condition[1].ToString("0")+"% · КПП "+c.Condition[2].ToString("0")+"%",new Rectangle(13,300,Width-24,22),11,Theme.Muted);Enabled=!entry.Dnf&&!entry.Finished;}
    static void Draw(Graphics g,string text,Rectangle r,int size,Color color,bool bold=false){using(var f=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))TextRenderer.DrawText(g,text,f,r,color,TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine);}
}
public class RaceLiveOverlay:GameOverlay {
    readonly Career state;internal readonly LiveSession Race;readonly Action save;readonly RaceControlPanel[] controls;readonly int round;readonly Dictionary<string,Font> fonts=new Dictionary<string,Font>();readonly Dictionary<int,double> rowY=new Dictionary<int,double>();
    readonly SoftButton pause=new SoftButton{Text="Пауза"},back=new SoftButton{Text="Сохранить и выйти"},continueRace=new SoftButton{Text="Продолжаем",Primary=true},pitBoth=new SoftButton{Text="Оба в боксы"};
    double nextTick,lastSave,lastFrame,eventShown;bool completed,wasEvent;
    public event Action Finished,Returned;internal event Action<double> FramePainted;
    protected override bool UsesSheet {get{return false;}}
    internal override bool NeedsBackdrop {get{return false;}}
    public RaceLiveOverlay(Career s,bool animated,Action persist):base(animated){state=s;round=s.Round;Race=s.Weekend.Live;save=persist;controls=Race.Entries.Where(e=>e.Team==s.Player).OrderBy(e=>Engine.Person(s,e.Id).Deal.Seat).Select(e=>new RaceControlPanel(s,e,Save)).ToArray();foreach(var control in controls)Controls.Add(control);foreach(var c in new[]{pause,back,continueRace,pitBoth})Controls.Add(c);pause.Click+=(o,e)=>{Race.Paused=!Race.Paused;pause.Text=Race.Paused?"Продолжить":"Пауза";Save();};back.Click+=(o,e)=>Cancel();continueRace.Click+=(o,e)=>{RaceDirector.Continue(state);nextTick=Clock.Elapsed.TotalSeconds+RaceDirector.TickSeconds;Save();};pitBoth.Click+=(o,e)=>{foreach(var c in controls)c.RequestPit();RaceDirector.Continue(state);nextTick=Clock.Elapsed.TotalSeconds+RaceDirector.TickSeconds;Save();};Resize+=(o,e)=>ArrangeControls();ArrangeControls();nextTick=RaceDirector.TickSeconds;}
    void Save(){save();lastSave=Clock.Elapsed.TotalSeconds;}
    void ArrangeControls(){int right=Math.Max(620,(int)(Width*.63));int w=Width-right-30;int ph=Math.Min(328,(Height-150)/2);for(int i=0;i<controls.Length;i++)controls[i].Bounds=new Rectangle(right,86+i*(ph+8),w,ph);pause.Bounds=new Rectangle(24,Height-54,126,35);back.Bounds=new Rectangle(164,Height-54,190,35);continueRace.Bounds=new Rectangle(48,Math.Min(Height-180,350),205,40);pitBoth.Bounds=new Rectangle(269,Math.Min(Height-180,350),205,40);}
    protected override void Advance(){if(Closing||completed)return;double now=Clock.Elapsed.TotalSeconds;if(lastFrame==0)lastFrame=now;double dt=Math.Min(.05,now-lastFrame);lastFrame=now;double rowHeight=Math.Min(28,(Height-180.0)/Math.Max(1,Race.Entries.Count));var order=Race.Entries.OrderBy(e=>e.Dnf?1:0).ThenBy(e=>e.RacePosition).ToArray();for(int i=0;i<order.Length;i++){double y;if(!rowY.TryGetValue(order[i].Id,out y))y=i*rowHeight;rowY[order[i].Id]=Animated?y+(i*rowHeight-y)*(1-Math.Exp(-dt*16)):i*rowHeight;}if(now>=nextTick){nextTick=now+RaceDirector.TickSeconds;if(!Race.Paused&&!Race.AwaitingEvent){try{RaceDirector.Step(state);}catch(Exception ex){Race.Paused=true;Race.Event="Ошибка расчёта: "+ex.Message;Race.AwaitingEvent=true;Save();}}foreach(var c in controls)c.Invalidate();}if(Race.AwaitingEvent&&!wasEvent)eventShown=now;wasEvent=Race.AwaitingEvent;continueRace.Visible=pitBoth.Visible=Race.AwaitingEvent;pause.Enabled=!Race.AwaitingEvent;if(now-lastSave>8)Save();if(Race.Finished){completed=true;Save();if(Finished!=null)Finished();}}
    internal void StepForTest(){Race.Paused=false;Race.AwaitingEvent=false;RaceDirector.Step(state);foreach(var c in controls)c.Invalidate();}
    protected override void OnPaint(PaintEventArgs e){if(FramePainted!=null)FramePainted(Clock.Elapsed.TotalMilliseconds);var g=e.Graphics;g.Clear(Theme.Background);g.SmoothingMode=SmoothingMode.AntiAlias;int right=Math.Max(620,(int)(Width*.63));int tw=right-48;Draw(g,"LIVE  /  "+Race.Name.ToUpperInvariant()+"  /  "+Data.Tracks[round].Country,new Rectangle(26,18,tw,30),22,Color.White,true);int lap=Race.Entries.Max(x=>x.Lap);Color flag=Race.Flag=="GREEN"?Color.FromArgb(91,210,145):Race.Flag=="RED"?Theme.Red:Color.FromArgb(245,198,73);Draw(g,"КРУГ "+Math.Min(Race.TargetLaps,lap+1)+" / "+Race.TargetLaps+"   •   "+Race.Weather+"   •   "+Race.Flag+(Race.Paused?"   / ПАУЗА":""),new Rectangle(27,55,tw,23),13,flag,true);Draw(g,"ПИЛОТ",new Rectangle(78,89,200,22),10,Theme.Muted,true);Draw(g,"ШИНЫ / ИЗНОС",new Rectangle(26+(int)(tw*.51),89,120,22),10,Theme.Muted,true);Draw(g,"ИНТЕРВАЛ",new Rectangle(26+(int)(tw*.74),89,90,22),10,Theme.Muted,true);Draw(g,"ЛИДЕР",new Rectangle(26+(int)(tw*.88),89,85,22),10,Theme.Muted,true);var order=Race.Entries.OrderBy(x=>x.Dnf?1:0).ThenBy(x=>x.RacePosition).ToArray();double rh=Math.Min(28,(Height-180.0)/Math.Max(1,order.Length));double lead=order.First(x=>!x.Dnf||order.All(z=>z.Dnf)).RaceTime;for(int i=0;i<order.Length;i++){var car=order[i];double animatedY;rowY.TryGetValue(car.Id,out animatedY);int y=116+(int)animatedY,h=(int)rh-2;using(var path=Theme.Round(new Rectangle(24,y,tw,h),5))using(var b=new SolidBrush(car.Team==state.Player?Color.FromArgb(66,26,30):Theme.Card))g.FillPath(b,path);Draw(g,car.RacePosition.ToString("00"),new Rectangle(31,y+3,35,h),12,car.Team==state.Player?Theme.Red:Theme.Muted,true);Theme.ImageFit(g,TeamLogos.Get(car.Team),new Rectangle(68,y+3,26,h-4));Draw(g,Engine.Person(state,car.Id).Name,new Rectangle(101,y+3,(int)(tw*.51)-79,h),12,car.Dnf?Theme.Muted:Color.White,true);int tx=26+(int)(tw*.51);Theme.ImageFit(g,TyrePhotos.Get(car.Tyre),new Rectangle(tx,y+1,26,h));Draw(g,car.Tyre+" / "+car.TyreWear.ToString("0")+"%",new Rectangle(tx+29,y+3,90,h),11,car.TyreWear>75?Theme.Red:Theme.Muted);double smooth=Animated?Theme.Ease(1-(nextTick-Clock.Elapsed.TotalSeconds)/RaceDirector.TickSeconds):1;double gap=car.PreviousGap+(car.RaceTime-lead-car.PreviousGap)*smooth;string interval=i==0?"LEADER":car.Dnf?"DNF":car.PittedThisTick?"PIT":car.Finished?"FIN":"+"+Math.Max(.02,car.RaceTime-order[i-1].RaceTime).ToString("0.00");Draw(g,interval,new Rectangle(26+(int)(tw*.74),y+3,90,h),11,car.PittedThisTick?Theme.Red:Theme.Muted);Draw(g,i==0?"—":car.Dnf?"DNF":"+"+Math.Max(0,gap).ToString("0.00"),new Rectangle(26+(int)(tw*.88),y+3,85,h),11,Theme.Muted);}
        if(Race.Log.Count>0)Draw(g,Race.Log[0],new Rectangle(374,Height-48,Math.Max(100,Width-405),30),11,Theme.Muted);if(Race.AwaitingEvent){double reveal=Animated?Theme.Ease((Clock.Elapsed.TotalSeconds-eventShown)/.16):1;using(var b=new SolidBrush(Color.FromArgb((int)(185*reveal),8,8,8)))g.FillRectangle(b,24,111,tw,Height-180);int top=Math.Min(Height-324,206)+(int)((1-reveal)*14);using(var path=Theme.Round(new Rectangle(34,top,tw-20,204),18))using(var b=new SolidBrush(Color.FromArgb(43,29,30)))using(var pen=new Pen(Theme.Red)){g.FillPath(b,path);g.DrawPath(pen,path);}Draw(g,Race.Flag=="GREEN"?"СООБЩЕНИЕ ИНЖЕНЕРА":Race.Flag=="RED"?"КРАСНЫЙ ФЛАГ":Race.Flag+" / НЕЙТРАЛИЗАЦИЯ",new Rectangle(49,top+18,tw-48,31),20,Theme.Red,true);Draw(g,Race.Event,new Rectangle(49,top+61,tw-50,70),14,Color.White,false,true);continueRace.Top=pitBoth.Top=top+148;}}
    void Draw(Graphics g,string text,Rectangle r,int size,Color color,bool bold=false,bool wrap=false){string key=size+"/"+bold;Font f;if(!fonts.TryGetValue(key,out f)){f=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel);fonts.Add(key,f);}TextRenderer.DrawText(g,text??"",f,r,color,TextFormatFlags.EndEllipsis|(wrap?TextFormatFlags.WordBreak:TextFormatFlags.SingleLine));}
    public override void Cancel(){if(Closing||completed)return;Race.Paused=true;Save();if(Returned!=null)Returned();}
    protected override void Dispose(bool disposing){if(disposing)foreach(var f in fonts.Values)f.Dispose();base.Dispose(disposing);}
}
public class PowerReplacementOverlay:GameOverlay {
    public event Action Replaced,Cancelled;
    protected override Size SheetSize {get{return new Size(760,355);}}
    public PowerReplacementOverlay(Career s,int seat,int kind,bool animated):base(animated){var car=Powertrain.Car(Engine.Team(s,s.Player),seat);double cost=Powertrain.ReplacementPrice(car,kind);LabelAt(Sheet,"ЗАМЕНА / "+Powertrain.Names[kind],28,24,700,38,25,true,Color.White);LabelAt(Sheet,"Машина "+(seat+1)+" • ресурс "+car.Condition[kind].ToString("0.0")+"% → 100%\nНовый агрегат №"+(car.Used[kind]+1)+" / сезонный лимит "+Powertrain.Limits[kind]+"\n"+(cost>0?"Стоимость: "+Engine.Money(cost)+". Пилот стартует с конца решётки следующего Гран-при.":"В пределах сезонного лимита. Без оплаты и штрафа."),30,82,690,126,16);var error=LabelAt(Sheet,"",30,215,690,40,12,false,Theme.Red);var confirm=new SoftButton{Text="Установить",Primary=true,Bounds=new Rectangle(459,280,270,43)};var back=new SoftButton{Text="Назад",Bounds=new Rectangle(30,280,150,43)};Sheet.Controls.Add(confirm);Sheet.Controls.Add(back);confirm.Click+=(o,e)=>{try{Powertrain.Replace(s,seat,kind);if(Replaced!=null)Replaced();}catch(Exception ex){error.Text=ex.Message;}};back.Click+=(o,e)=>Cancel();}
    public override void Cancel(){if(!Closing&&Cancelled!=null)Cancelled();}
}
public partial class ManagerForm {
    int PowertrainPage(){var s=State;var team=Engine.Team(s,s.Player);Heading("POWER UNIT / SEASON ALLOCATION","Силовая установка");int y=193;Box(X,y,W,97);TextAt(team.Engine+" / мощность "+team.EngineRating.ToString("0.0")+" / надёжность "+team.EngineReliability.ToString("0.0"),X+18,y+13,W-35,19,white,true);TextAt("Лимит на машину: 4 ДВС · 2 ERS · 4 КПП. Сверх лимита: $8 / $6 / $5 млн и конец решётки следующего Гран-при.",X+18,y+52,W-35,12,muted,false,34);y+=115;for(int seat=0;seat<2;seat++){int st=seat;var c=Powertrain.Car(team,seat);var driver=Engine.Drivers(s,s.Player).FirstOrDefault(p=>p.Deal.Seat==st);Box(X,y,W,318);TextAt("МАШИНА "+(seat+1)+" / "+(driver==null?"Вакансия":driver.Name),X+18,y+16,W-36,22,white,true,35);TextAt(c.GridPenalty?"ШТРАФ: конец решётки следующего Гран-при":"Штрафов за агрегаты нет",X+18,y+53,W-36,12,c.GridPenalty?red:muted);for(int k=0;k<3;k++){int kind=k,cy=y+90+k*72;TextAt(Powertrain.Names[k],X+18,cy,185,16,white,true);TextAt(c.Condition[k].ToString("0.0")+"% / №"+c.Used[k]+" / лимит "+Powertrain.Limits[k],X+210,cy,W-420,14,c.Condition[k]<25?red:muted);Progress(X+18,cy+33,W-225,c.Condition[k]/100,c.Condition[k]<25?red:Color.FromArgb(94,197,145));Btn("Заменить / "+(Powertrain.ReplacementPrice(c,k)>0?Engine.Money(Powertrain.ReplacementPrice(c,k)):"лимит"),X+W-195,cy-1,176,()=>{var overlay=new PowerReplacementOverlay(s,st,kind,Preferences.Animations);overlay.Cancelled+=()=>CloseOverlay(null);overlay.Replaced+=()=>{SaveSilent();CloseOverlay(null);};ShowOverlay(overlay);},true,37);}y+=336;}TextAt("Атака увеличивает отдачу и расход ресурса. Сохранение снижает темп и износ. ДВС и ERS зависят от режима двигателя и охлаждения, КПП — также от пилотажа. Низкий ресурс ухудшает темп и повышает риск отказа.",X,y,W,14,muted,false,66);return y+95;}
    void BeginLiveRace(string name){int round=State.Round,year=State.Year;Engine.Start(State);var live=State.Weekend.Live;if(!live.TickRace){RaceDirector.MigrateLive(State);Notify("Сохранённая гонка переведена на интерактивное табло.");}SaveSilent();var overlay=new RaceLiveOverlay(State,Preferences.Animations,SaveSilent);overlay.Returned+=()=>CloseOverlay(()=>{Page="race";StartTransition();});overlay.Finished+=()=>CloseOverlay(()=>{Page="race";View="game";Scroll=0;scrollTarget=0;SaveSilent();PresentSession(name,round,year);});ShowOverlay(overlay);}
}
